/** Real loopback Relay + Host topology controlled by framed test-only commands. */
public final class Stage5TopologyFixture {
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final String TENANT_ID = "stage5-tenant";
    private static final String HOST_ID = "stage5-host";

    private final Path root;
    private final String webOrigin;
    private final KeyPair ownerIdentity;
    private final DurableDeviceStore devices;
    private RelayApplication relay;
    private HostRuntime host;
    private String ownerAccessToken;

    private Stage5TopologyFixture(Path root, String webOrigin) throws Exception {
        this.root = root;
        this.webOrigin = webOrigin;
        ownerIdentity = p256();
        devices = new DurableDeviceStore();
        startRelay(true);
        startHost();
    }

    public static void main(String[] args) throws Exception {
        if (args.length != 1) throw new IllegalArgumentException("usage: Stage5TopologyFixture WEB_ORIGIN");
        Path root = Files.createTempDirectory("ji-stage5-topology-");
        try (var fixture = new Stage5TopologyFixture(root, args[0]);
             var control = new ServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            System.out.println("STAGE5_TOPOLOGY_READY DIRECT " + fixture.host.origin()
                    + " RELAY " + fixture.management() + " WSS " + fixture.webSocket()
                    + " CONTROL " + control.getLocalPort());
            System.out.flush();
            try (var connection = control.accept();
                 var commands = new BufferedReader(new InputStreamReader(
                         connection.getInputStream(), StandardCharsets.US_ASCII));
                 var response = new DataOutputStream(connection.getOutputStream())) {
                String command;
                while ((command = commands.readLine()) != null) {
                    if ("STOP".equals(command)) break;
                    if ("ISSUE_LOCAL_TOKEN".equals(command)) {
                        frame(response, fixture.host.server().issueLaunchToken());
                    } else if ("ISSUE_RELAY_ENROLLMENT".equals(command)) {
                        frame(response, fixture.enrollment());
                    } else if ("RESTART_RELAY".equals(command)) {
                        fixture.restartRelay();
                        frame(response, Map.of("restarted", "relay"));
                    } else if ("RESTART_HOST".equals(command)) {
                        fixture.restartHost();
                        frame(response, Map.of("restarted", "host"));
                    } else if (command.startsWith("REVOKE_RELAY_DEVICE ")) {
                        fixture.revokeRelayDevice(command.substring("REVOKE_RELAY_DEVICE ".length()));
                        frame(response, Map.of("revoked", true));
                    } else {
                        throw new IllegalArgumentException("unexpected control command");
                    }
                }
            }
        } finally {
            deleteTree(root);
        }
    }

    private URI management() { return URI.create("http://127.0.0.1:" + relay.port() + "/"); }
    private URI webSocket() { return URI.create("ws://127.0.0.1:" + relay.webSocketPort() + "/relay/v1"); }

    private void startRelay(boolean bootstrap) throws Exception {
        int managementPort = relay == null ? 0 : relay.port();
        int webSocketPort = relay == null ? 0 : relay.webSocketPort();
        relay = new RelayApplication(root.resolve("relay"), "127.0.0.1", managementPort, webSocketPort,
                Map.of("JI_RELAY_TERMINAL_BOOTSTRAP", "fixture-terminal",
                        "JI_RELAY_ALLOWED_ORIGIN", webOrigin));
        if (bootstrap) bootstrapOwner();
        else ownerAccessToken = [REDACTED_CREDENTIAL]"owner-restart-" + System.nanoTime());
    }

    private void bootstrapOwner() throws Exception {
        JsonNode bootstrap = json(post(management().resolve("api/v1/bootstrap"), Map.of("tenantId", TENANT_ID))
                .header("X-JI-Terminal-Bootstrap", "fixture-terminal").build(), 201);
        JsonNode owner = json(post(management().resolve("api/v1/owner/claim"), Map.of(
                "tenantId", TENANT_ID, "pin", bootstrap.path("pin").asText(),
                "secret", bootstrap.path("secret").asText(), "deviceId", "fixture-owner",
                "authAlgorithm", HostDeviceStore.DEVICE_AUTH_ALGORITHM,
                "publicKey", Base64.getEncoder().encodeToString(ownerIdentity.getPublic().getEncoded()))).build(), 201);
        ownerAccessToken = [REDACTED_CREDENTIAL]"accessToken").asText();
    }

    private void startHost() throws Exception {
        ownerAccessToken = [REDACTED_CREDENTIAL]"owner-host-" + System.nanoTime());
        JsonNode access = json(authorized(management().resolve("api/v1/hosts/" + HOST_ID + "/access"),
                ownerAccessToken, Map.of()).build(), 201);
        host = HostRuntime.start(root, devices, management(), webSocket(), access.path("accessToken").asText());
        await(() -> relay.hostPresent(TENANT_ID, HOST_ID), "Host presence was not registered");
    }

    private Map<String, Object> enrollment() throws Exception {
        ownerAccessToken = [REDACTED_CREDENTIAL]"owner-invite-" + System.nanoTime());
        JsonNode invitation = json(authorized(management().resolve("api/v1/invitations"), ownerAccessToken,
                Map.of("hostIds", List.of(HOST_ID))).build(), 201);
        json(authorized(management().resolve("api/v1/invitations/" + invitation.path("invitationId").asText()
                + "/confirm"), ownerAccessToken,
                Map.of("fingerprint", invitation.path("fingerprint").asText())).build(), 200);
        return Map.of(
                "managementUrl", management().toString(), "webSocketUrl", webSocket().toString(),
                "tenantId", TENANT_ID, "hostId", HOST_ID,
                "invitationId", invitation.path("invitationId").asText(),
                "secret", invitation.path("secret").asText(),
                "fingerprint", invitation.path("fingerprint").asText(),
                "launchToken", host.server().issueLaunchToken());
    }

    private void restartRelay() throws Exception {
        int managementPort = relay.port();
        int webSocketPort = relay.webSocketPort();
        relay.close();
        relay = new RelayApplication(root.resolve("relay"), "127.0.0.1", managementPort, webSocketPort,
                Map.of("JI_RELAY_TERMINAL_BOOTSTRAP", "fixture-terminal",
                        "JI_RELAY_ALLOWED_ORIGIN", webOrigin));
        ownerAccessToken = [REDACTED_CREDENTIAL]"owner-relay-restarted-" + System.nanoTime());
        await(() -> relay.hostPresent(TENANT_ID, HOST_ID), "Host did not reconnect after Relay restart");
    }

    private void restartHost() throws Exception {
        int restPort = host.server().port();
        int hcpPort = host.server().hcpPort();
        host.close();
        ownerAccessToken = [REDACTED_CREDENTIAL]"owner-host-restarted-" + System.nanoTime());
        JsonNode access = json(authorized(management().resolve("api/v1/hosts/" + HOST_ID + "/access"),
                ownerAccessToken, Map.of()).build(), 201);
        host = HostRuntime.start(root, devices, management(), webSocket(), access.path("accessToken").asText(),
                restPort, hcpPort);
        await(() -> relay.hostPresent(TENANT_ID, HOST_ID), "Host did not restore Relay presence");
    }

    private void revokeRelayDevice(String deviceId) throws Exception {
        ownerAccessToken = [REDACTED_CREDENTIAL]"owner-revoke-" + System.nanoTime());
        HttpResponse<String> response = HttpClient.newHttpClient().send(HttpRequest.newBuilder(
                management().resolve("api/v1/devices/" + encode(deviceId)))
                .header("Authorization", "Bearer " + ownerAccessToken).DELETE().build(),
                HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() != 200) throw new IllegalStateException("Relay device revoke failed");
    }

    private String authenticateOwner(String connectionId) throws Exception {
        JsonNode challenge = json(post(management().resolve("api/v1/auth/challenge"), Map.of(
                "tenantId", TENANT_ID, "deviceId", "fixture-owner", "connectionId", connectionId,
                "authAlgorithm", HostDeviceStore.DEVICE_AUTH_ALGORITHM)).build(), 201);
        Signature signer = Signature.getInstance("SHA256withECDSA");
        signer.initSign(ownerIdentity.getPrivate());
        signer.update(DeviceChallengeService.payload(
                TENANT_ID, "fixture-owner", connectionId, challenge.path("nonce").asText()));
        JsonNode verified = json(post(management().resolve("api/v1/auth/verify"), Map.of(
                "tenantId", TENANT_ID, "deviceId", "fixture-owner", "connectionId", connectionId,
                "authAlgorithm", HostDeviceStore.DEVICE_AUTH_ALGORITHM,
                "signature", Base64.getEncoder().encodeToString(signer.sign()))).build(), 200);
        return verified.path("accessToken").asText();
    }

    @Override public void close() {
        if (host != null) host.close();
        if (relay != null) relay.close();
        devices.close();
    }

    private static void frame(DataOutputStream output, Object value) throws Exception {
        byte[] bytes = MAPPER.writeValueAsBytes(value);
        output.writeInt(bytes.length);
        output.write(bytes);
        output.flush();
        java.util.Arrays.fill(bytes, (byte) 0);
    }

    private static HttpRequest.Builder post(URI uri, Object body) throws Exception {
        return HttpRequest.newBuilder(uri).header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofByteArray(MAPPER.writeValueAsBytes(body)));
    }

    private static HttpRequest.Builder authorized(URI uri, String token, Object body) throws Exception {
        return post(uri, body).header("Authorization", "Bearer " + token);
    }

    private static JsonNode json(HttpRequest request, int expectedStatus) throws Exception {
        HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() != expectedStatus) {
            throw new IllegalStateException("fixture management request failed: " + response.statusCode());
        }
        return MAPPER.readTree(response.body());
    }

    private static String encode(String value) {
        return java.net.URLEncoder.encode(value, StandardCharsets.UTF_8);
    }

    private static KeyPair p256() throws Exception {
        KeyPairGenerator generator = KeyPairGenerator.getInstance("EC");
        generator.initialize(new ECGenParameterSpec("secp256r1"));
        return generator.generateKeyPair();
    }

    private static void await(java.util.function.BooleanSupplier condition, String failure) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
        while (!condition.getAsBoolean() && System.nanoTime() < deadline) Thread.sleep(20);
        if (!condition.getAsBoolean()) throw new IllegalStateException(failure);
    }

    private static void deleteTree(Path root) throws Exception {
        if (!Files.exists(root)) return;
        try (var paths = Files.walk(root)) {
            for (Path path : paths.sorted(java.util.Comparator.reverseOrder()).toList()) Files.deleteIfExists(path);
        }
    }

    private record HostRuntime(
            LocalHostServer server, SessionApplicationService sessions, NoiseKeyPair noise) implements AutoCloseable {
        private static HostRuntime start(
                Path root, DurableDeviceStore devices, URI management, URI socket, String hostAccessToken)
                throws Exception {
            return start(root, devices, management, socket, hostAccessToken, 0, 0);
        }

        private static HostRuntime start(
                Path root, DurableDeviceStore devices, URI management, URI socket, String hostAccessToken,
                int restPort, int hcpPort) throws Exception {
            var store = new PersistentHostStore(new SqliteHostStorePersistence(root.resolve("host.db")));
            var provider = new ScriptedModelProvider();
            for (int index = 0; index < 32; index++) {
                provider.enqueue(List.of(new ScriptedModelProvider.Step.Text("reply-" + index),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
            }
            var permissions = new PermissionBroker(Clock.systemUTC());
            var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                    .permissionDecider(permissions).build();
            var sessions = new SessionApplicationService(runtime);
            var tokens = new LocalTokenService(new SecureRandom(), Clock.systemUTC());
            var registry = new HostDeviceRegistry(HOST_ID, tokens, devices);
            var profiles = new ProviderProfileApplicationService(new MemoryProviderProfileStore(), store);
            profiles.save(new ProviderProfileApplicationService.Command(
                    "faux", -1, ProviderProtocolFamily.OPENAI_COMPATIBLE, URI.create("https://provider.invalid"),
                    CredentialReference.none(), Map.of(), List.of(new ProviderModel(
                            "faux-1", "Faux 1", java.util.Set.of(), Map.of())), "faux-1", Map.of()));
            var resources = resources();
            NoiseKeyPair noise = devices.noise();
            var artifacts = new FileArtifactStore(root.resolve("artifacts"), ArtifactLimits.defaults());
            var server = new LocalHostServer(sessions, permissions, new PromptApplicationService(sessions, store),
                    new ModelRef("faux", "faux-1"), tokens, restPort, hcpPort, artifacts, profiles, resources,
                    registry, "local");
            var connector = new HostRelayConnector(management, socket, TENANT_ID, HOST_ID,
                    identity(devices, noise), registry,
                    new HostDeviceChallengeService(registry, HOST_ID, Clock.systemUTC(), new SecureRandom()),
                    server.hcpGateway(), sessions, () -> hostAccessToken);
            server.connectRelay(connector);
            return new HostRuntime(server, sessions, noise);
        }

        private URI origin() { return URI.create("http://127.0.0.1:" + server.port()); }

        @Override public void close() {
            server.close();
            sessions.close();
        }

        private static ResourceApplicationService resources() {
            var identity = new ProjectTrustStore.ProjectIdentity("project-1", ".");
            var trust = new MemoryTrustStore();
            var snapshot = new ResourceApplicationService.Snapshot(1, "d".repeat(64), true, List.of(
                    new ResourceApplicationService.Resource("resource-1", "context", "project", "workspace",
                            "AGENTS.md", "1", "e".repeat(64), "awaiting_trust", "")));
            return new ResourceApplicationService(identity, trust, () -> snapshot, ignored -> snapshot,
                    Clock.systemUTC());
        }

        private static HostRelayConnector.HostIdentity identity(DurableDeviceStore devices, NoiseKeyPair noise) {
            return new HostRelayConnector.HostIdentity() {
                @Override public byte[] authenticationPublicKey() { return devices.identity().getPublic().getEncoded(); }
                @Override public byte[] noisePublicKey() { return noise.publicKey(); }
                @Override public byte[] sign(byte[] payload) {
                    try {
                        Signature signer = Signature.getInstance("Ed25519");
                        signer.initSign(devices.identity().getPrivate());
                        signer.update(payload);
                        return signer.sign();
                    } catch (java.security.GeneralSecurityException failure) {
                        throw new IllegalStateException(failure);
                    }
                }
                @Override public NoiseHandshake responder(RelayProtocol.Route route) {
                    return new NoiseHandshake(false, noise, route);
                }
            };
        }
    }

    private static final class DurableDeviceStore implements HostDeviceStore {
        private final KeyPair identity;
        private final byte[] noisePrivateKey;
        private final byte[] noisePublicKey;
        private final Map<String, Device> paired = new ConcurrentHashMap<>();

        private DurableDeviceStore() throws Exception {
            identity = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
            try (NoiseKeyPair value = NoiseKeyPair.generate()) {
                noisePrivateKey = value.privateKey();
                noisePublicKey = value.publicKey();
            }
        }
        private NoiseKeyPair noise() { return NoiseKeyPair.fromPrivateKey(noisePrivateKey); }
        @Override public KeyPair identity() { return identity; }
        @Override public Optional<byte[]> noisePrivateKey() { return Optional.of(noisePrivateKey.clone()); }
        @Override public Optional<byte[]> noisePublicKey() { return Optional.of(noisePublicKey.clone()); }
        @Override public Optional<Device> device(String deviceId) { return Optional.ofNullable(paired.get(deviceId)); }
        @Override public List<Device> devices() { return List.copyOf(paired.values()); }
        @Override public void save(Device device) { paired.put(device.deviceId(), device); }
        @Override public void remove(String deviceId) { paired.remove(deviceId); }
        @Override public void close() { java.util.Arrays.fill(noisePrivateKey, (byte) 0); }
    }

    private static final class MemoryTrustStore implements ProjectTrustStore {
        private TrustDecision value;
        @Override public Optional<TrustDecision> find(ProjectIdentity project) { return Optional.ofNullable(value); }
        @Override public TrustDecision decide(TrustCommand command) {
            value = new TrustDecision(command.project(), command.fingerprint(), command.decision(),
                    command.expectedRevision() + 1, command.decidedAt());
            return value;
        }
    }
}
